"""Session-authored independent legal judgments after full visible and primary-text reads."""
J={}
def add(supported,reason,refs,*texts):
 for text in texts:
  assert text not in J,text
  J[text]=(supported,reason,refs)
M='ma247-9';P='cfr45-164.502';D='cfr45-160.103'
add(True,'9.16(7)은 dispensing 때 필요한 기존 투약정보의 즉시 검색을, 9.17(1)(g),(i)는 알레르기와 용법 변화를 별도로 검토하도록 한다. MassPAT 조회 한 번으로 그 전부를 대신할 수 없다.',[(M,'9.16(7), 9.17(1)(g),(i)')],"A MassPAT query does not replace the patient's full relevant DUR and directions review.")
add(False,'즉시 검색할 수 없는 profile은 9.16(7)의 전산 검색 의무를 충족하지 않는다. 필요한 정보 확보의 reasonable effort 기준과 시스템의 immediate retrieval 요건을 혼동했다.',[(M,'9.16(7)')],'A profile that cannot be retrieved when dispensing meets the immediate-retrieval purpose.')
add(False,'정확한 제품·수량 확인 뒤에도 therapeutic duplication에 대한 DUR 및 적절한 조치·문서화 의무가 남는다.',[(M,'9.04(1), 9.17(1)(b),(2)')],'Barcode and count verification complete DUR even when a duplication remains unresolved.')
add(True,'제품·수량 일치와 therapeutic duplication에 대한 임상적 검토는 다른 판단이다. 9.17(2)의 적절한 조치가 필요하다.',[(M,'9.04(1), 9.17(1)(b),(2)')],'Correct product and count do not resolve the separate therapeutic-duplication concern.')
add(False,'계수의 정확성은 처방 발행의 진정성·정당한 의학적 목적을 증명하지 않는다. 연방 corresponding responsibility는 controlled-substance 처방의 범위에서 적용된다.',[(M,'9.04(1), 9.15'),('cfr21-1306.04','1306.04(a)')],'An accurately counted product establishes that the prescription is authentic.')
add(True,'최종 제품 검증과 처방의 정당성은 별개이다. 1306.04(a)의 corresponding responsibility는 연방 controlled substance에 관한 의무이며 모든 일반 물품으로 무제한 확장하지 않는다.',[(M,'9.04(1), 9.15'),('cfr21-1306.04','1306.04(a)')],'Prescription authenticity and corresponding responsibility are distinct from final physical-product verification.')
add(True,'알레르기 정보를 알아보지 않은 빈칸은 확인된 음성 병력이 아니다. 9.16(7)(b)의 reasonable effort와 9.17(1)(g)의 검토에 필요한 사실이 아직 없는 상태다.',[(M,'9.16(7)(b), 9.17(1)(g)')],'An empty allergy field is not the same as a confirmed negative allergy history.')
add(False,'정보 부재를 no known allergies로 단정할 근거가 없다. 법은 합리적으로 정보를 구하여 기록·유지하도록 하며 근거 없는 음성 기록을 허용하는 면책규정이 아니다.',[(M,'9.16(7)(b), 9.17(1)(g)')],'A blank allergy field is sufficient evidence that the patient has no allergies.')
add(True,'9.01(21)의 실제 REMS 요건 준수는 9.16의 처방·profile 기록과 c.94C §21A의 상담 거절 등 적용 기록 의무를 없애지 않는다. 모든 상담에 별도 문서가 무조건 필요하다고 확장하지 않는다.',[(M,'9.01(21), 9.16(1),(7), 9.18'),('ma94c-21a','§21A: patient information and refusal records')],'One stored REMS authorization does not replace other applicable records with different purposes.')
add(False,'REMS 항목 하나로 서로 목적·근거가 다른 모든 처방·profile·상담 거절 기록을 대체할 수 없다. 실제 적용되는 각 기록을 유지해야 한다.',[(M,'9.01(21), 9.16(1),(7), 9.18'),('ma94c-21a','§21A: patient information and refusal records')],'A REMS entry in the chart replaces every counseling and dispensing record.')
add(False,'9.16(7)(d)는 약물치료와 관련된 약사의 의견을 확보·기록·유지할 대상으로 정한다. 거래 종료만으로 필요한 임상 문제를 삭제하는 규정은 없다.',[(M,'9.16(7)(d)')],'Clinical concerns should be removed from the profile once the current transaction closes.')
add(False,'관련 정보를 고의로 알아보지 않는 행위는 reasonable effort를 충족하지 않는다. 환자가 합리적 질문에 답하지 않는 상황과 다르다.',[(M,'9.16(7)(a)-(d)')],'Patient-profile obligations are satisfied by deliberately leaving relevant fields unexamined.')
add(True,'각 인적정보·병력·투약·치료 관련 의견에 대한 reasonable effort가 기준이다. 모든 정보를 반드시 완전하게 확보해야 한다는 절대의무로 바꾸지 않는다.',[(M,'9.16(7)(a)-(d)')],'The pharmacy must make the described reasonable effort to obtain relevant profile information.')
add(True,'FDA 승인 Medication Guide와 비승인 CMI는 구분된다. 필요한 Guide는 FDA 승인 내용·형식을 충족하고 dispensing 때 제공해야 하므로 일반 소프트웨어 leaflet이라는 사실만으로 대체되지 않는다.',[('cfr21-208.20','208.20(a)(2),(6)'),('cfr21-208.24','208.24(a),(e)'),('fda-medguides','What types of patient labeling are available; What are Medication Guides')],'A generic consumer leaflet is not automatically a substitute for the required FDA-approved Medication Guide.')
add(False,'어떤 소프트웨어 leaflet이든 필요한 Guide를 충족한다는 주장은 틀리다. FDA 승인 여부·내용·형식과 실제 제공 요건이 중요하다.',[('cfr21-208.20','208.20(a)'),('cfr21-208.24','208.24(a),(e)'),('fda-medguides','CMI and Medication Guide distinctions')],"Any software leaflet necessarily fulfills a product's required Medication Guide.")
add(True,'FDA는 모든 Guide가 승인 labeling의 일부이나 소수만 REMS 일부라고 설명한다. REMS의 구체적 enrollment·ETASU는 제품별로 따로 정하므로 Guide 존재만으로 enrollment를 추론할 수 없다.',[('fda-rems-components','Communicating to Patients; Required Activities or Clinical Interventions')],'A Medication Guide requirement does not by itself prove a current REMS enrollment requirement.')
add(False,'Guide의 존재와 현재 active REMS enrollment는 동일하지 않다. 일부 REMS만 인증·등록 등 추가 활동을 요구한다.',[('fda-rems-components','Communicating to Patients; Required Activities or Clinical Interventions')],'The existence of a Medication Guide proves that REMS enrollment is required.')
add(False,'208.24(e)는 제품이 환자 또는 대리인에게 dispensing될 때 제공하도록 하며 최초 조제만으로 한정하지 않는다. 208.26 면제 가능성은 있으나 refill을 일괄 제외하지 않는다.',[('cfr21-208.24','208.24(e)')],'Medication Guides are categorically limited to the first dispensing and excluded from refills.')
add(True,'일반적으로 각 dispensing 때 Guide가 필요하고 refill도 그 대상이 될 수 있다. may와 applicable rule 표현은 208.26 면제 가능성을 남기므로 과도한 절대화가 아니다.',[('cfr21-208.24','208.24(e)')],'Required information may also be needed at refills under the applicable Medication Guide rule.')
add(False,'CDC의 VIS는 백신의 이익·위험을 알리는 문서이고 해당 백신 접종 전에 제공하는 정보다. 모든 처방약의 일반 leaflet과 동일 문서가 아니다.',[('cdc-vis',"What's a VIS; VISs are required by law")],"A VIS is the same document as every prescription medicine's generic consumer leaflet.")
add(True,'310.501(a)는 oral contraceptive의 각 환자용 dispensed package 안에 또는 함께 PPI를 제공하도록 한다. 이전 package에서 받았다는 사실은 새 package 의무의 예외가 아니다.',[('cfr21-310.501','310.501(a),(b)(1)')],'The applicable PPI accompanies each dispensed oral-contraceptive package.')
add(False,'이전 insert 수령을 이후 package 제공 의무의 면제로 정한 문언이 없다. 각 package 의무를 적용한다.',[('cfr21-310.501','310.501(a),(b)(1)')],'An earlier package insert eliminates the requirement for subsequent dispensed packages.')
add(True,'급성기 병원/LTCF의 oral contraceptive에는 최초 투여 전과 치료 지속 중 매 30일 제공 경로가 있다. estrogen에도 병행 규정이 있지만 제품별 적용 조항을 구분한다.',[('cfr21-310.501','310.501(b)(2)'),('cfr21-310.515','310.515(b)(3),(e)')],'The institutional rule includes provision before first administration and every 30 days while therapy continues.')
add(False,'310.501(b)(2)가 명시한 first administration 전과 계속 치료 중 30일 정보 경로를 정반대로 부정한다.',[('cfr21-310.501','310.501(b)(2)')],'The institutional pathway has no first-administration or continuing 30-day information requirement.')
add(False,'PPI 규정은 환자정보 제공 시점에 관한 것이다. 그 30일을 처방 자체의 refill 유효기간으로 정하지 않는다.',[('cfr21-310.501','310.501(a),(b)(2)'),(M,'9.04(12)-(13)')],"The PPI's 30-day interval establishes the prescription's refill validity.")
add(True,'환자정보 제공의 30일 주기와 처방 refill 권한·유효기간은 각기 다른 규칙이다. 310.501은 처방 연장 권한을 부여하지 않는다.',[('cfr21-310.501','310.501(b)(2)'),(M,'9.04(12)-(13)')],'The PPI information clock is separate from prescription refill validity.')
add(False,'310.515(e)는 estrogen-progestogen oral contraceptive를 해당 조항에서 제외하고 310.501로 보낸다. estrogen 함유라는 이유만으로 모든 제품에 동일 조항을 무차별 적용할 수 없다.',[('cfr21-310.501','310.501(a)'),('cfr21-310.515','310.515(e)')],'Every estrogen-containing product is governed by an identical PPI provision regardless of product type.')
add(True,'MA §21A 및 9.18은 cash 결제 자체를 예외로 두지 않는다. 42 CFR 456.705의 Medicaid state-plan DUR·counseling 틀과 독립된 주 의무가 병존한다. inpatient 예외는 별도이다.',[('ma94c-21a','§21A: offer to counsel and inpatient exception'),(M,'9.17(1), 9.18(1),(4),(10)'),('cfr42-456.705','456.705(a),(c),(d)')],"Massachusetts's independent counseling obligations are not confined to Medicaid payment.")
add(False,'cash 결제라는 이유로 MA의 독립 상담 의무가 사라지지 않는다. 본문은 inpatient가 아닌 일반 pharmacy 상황이다.',[('ma94c-21a','§21A: offer to counsel'),(M,'9.18(1),(4),(10)')],'Cash payment removes Massachusetts counseling obligations because Medicaid funds are absent.')
add(True,'§21A는 배송 시 pharmacist와 소통하는 toll-free access 및 번호 labeling 경로를 정한다. leaflet 제공 하나로 그 경로·offer·실제 상담까지 모두 충족했다고 확정할 수 없다.',[('ma94c-21a','§21A: offsite delivery, toll-free telephone and container label'),(M,'9.18(1),(4),(8)'),('cfr42-456.705','456.705(c)(1),(2)(i)')],'Written information alone does not establish compliance with every applicable mail-service counseling requirement.')
add(False,'배송 leaflet만으로 모든 상담 이용 요건 충족을 확정할 수 없다. 적용 전화 상담 접근 및 offer와 실제 상담을 확인해야 한다.',[('ma94c-21a','§21A: offsite delivery and toll-free access'),(M,'9.18(1),(4),(8)')],'Enclosing a leaflet conclusively satisfies all mail-service counseling requirements.')
add(True,'제안, 수락 후 상담, 거절 기록은 다른 사실이다. §21A는 거절 기록과 무기록 시 상담 제공의 추정까지 별도로 정한다.',[('ma94c-21a','§21A: offer, acceptance/refusal and record presumption'),(M,'9.18(1),(3),(4)')],'Offer, actual counseling, and documented refusal describe different events.')
add(False,'offer와 실제 counseling 및 refusal은 동일 사건이 아니다. 거절·수락 여부를 사실대로 구분해야 한다.',[('ma94c-21a','§21A: offer, acceptance/refusal and record presumption')],'The terms offer, counseling, and refusal identify the same event for legal records.')
add(True,'§21A와 9.17·9.18은 DUR 및 상담을 별도 의무로 정한다. 한 과정을 마쳤다는 사실만으로 다른 적용 의무가 모두 면제되지 않는다.',[('ma94c-21a','§21A: prospective review and counseling'),(M,'9.17, 9.18')],'Prospective review, patient information, and counseling duties must be connected without treating one as a substitute for the others.')
add(False,'prospective review 완료는 모든 환자정보·상담 의무를 제거하는 면제 사유가 아니다. 별도 요건을 적용해야 한다.',[('ma94c-21a','§21A: prospective review and counseling'),(M,'9.17, 9.18')],'Completing prospective review removes the need for all patient-information and counseling duties.')
add(True,'160.103의 PHI는 전자 외 어떤 형태·매체로 전달·유지되는 식별가능 건강정보도 포함한다. 따라서 종이 라벨도 해당할 수 있다. covered-entity 및 정보 정의의 실제 조건은 유지한다.',[(D,'160.103: Health information, Individually identifiable health information, Protected health information'),(P,'164.502(a)'),('cfr45-164.530','164.530(c)')],"Identifiable health information on paper can fall within the Privacy Rule's protection.")
add(False,'비전자 종이라는 이유만으로 PHI 범위에서 제외되지 않는다. 정의는 any other form or medium을 포함한다.',[(D,'160.103: Protected health information'),(P,'164.502(a)')],'Paper prescription labels are outside privacy protection because they are not electronic.')
add(True,'구두로 전달되는 식별가능 건강정보도 정의상 health information/PHI가 될 수 있다. 답은 자동 위반이라고 단정하지 않고 can implicate로 적절한 허용·보호 검토를 요구한다.',[(D,'160.103: Health information, Protected health information'),(P,'164.502(a)(1)(iii)'),('cfr45-164.530','164.530(c)')],'An oral disclosure can implicate privacy even when no computer file is transmitted.')
add(False,'email 전송 여부는 구두 식별가능 건강정보의 privacy 적용을 결정하지 않는다. incidental disclosure도 적절한 허용 근거·safeguards 조건을 보아야 한다.',[(D,'160.103: Health information, Protected health information'),(P,'164.502(a)'),('cfr45-164.530','164.530(c)')],'Speaking identifiable health information is outside privacy rules unless it is also emailed.')
add(True,'Security subpart C의 164.302는 ePHI에 적용되지만 Privacy Rule의 PHI 정의는 종이·구두도 포함한다. 두 범위를 동일시하지 않는다.',[('cfr45-164.302','164.302'),(D,'160.103: Electronic protected health information; Protected health information')],"The Security Rule's electronic-PHI focus differs from the broader Privacy Rule.")
add(False,'Security의 ePHI 적용이 더 넓은 Privacy의 PHI 정의를 전자로 축소하지 않는다.',[('cfr45-164.302','164.302'),(D,'160.103: Protected health information')],"The Security Rule's electronic focus narrows all Privacy Rule protection to electronic files.")
add(False,'거래 종료나 약국 소재만으로 식별가능 건강정보가 공개 정보가 되는 예외는 없다. 정보 유형과 허용 목적·수령자·보호 조치를 판단해야 한다.',[(D,'160.103: Protected health information'),(P,'164.502(a)'),(M,'9.01(16)')],'Any information located in a pharmacy is automatically public once a transaction ends.')
add(True,'covered pharmacy를 대신해 식별가능 청구정보를 처리하는 billing 기능은 160.103 BA 정의에 열거된다. 164.502(e)·504(e)의 필요한 계약·보호 확인이 필요하다.',[(D,'160.103: Business associate (1)(i)'),(P,'164.502(e)'),('cfr45-164.504','164.504(e)')],'The billing arrangement requires evaluation of the applicable business-associate and agreement obligations.')
add(False,'billing support라는 명칭은 법적 BA 예외가 아니다. 약국을 대신하여 PHI를 취급하는 실질 업무가 판단 기준이다.',[(D,'160.103: Business associate (1)(i)'),(P,'164.502(e)')],'A vendor is excluded from business-associate obligations whenever it calls its service billing support.')
add(True,'160.103은 실제 on-behalf-of 활동 및 PHI 처리로 BA를 정의한다. 업체의 마케팅 명칭이 의무를 결정하지 않는다.',[(D,'160.103: Business associate (1),(4)')],"The actual functions and handling of PHI matter more than the vendor's marketing label.")
add(False,'chosen title만으로 BA 해당성을 결정하지 않는다. PHI를 누구를 대신해 어떤 기능으로 취급하는지 확인해야 한다.',[(D,'160.103: Business associate (1),(4)')],'Whether an entity is a business associate depends only on its chosen business title.')
add(True,'치료를 위해 다른 health care provider에게 공개하는 경우는 160.103 BA 정의 (4)(i)의 예외이다. 별도 위탁업무 관계가 있을 수 있지만 이 treatment 공개만으로 BA가 되지는 않는다.',[(D,'160.103: Business associate (4)(i)'),('cfr45-164.506','164.506(c)(2)')],'A treatment disclosure to another provider is not automatically the same as a business-associate service relationship.')
add(False,'치료 공개를 받는 모든 provider가 자동으로 BA가 되는 것은 아니다. 정의의 치료 provider 예외를 무시한다.',[(D,'160.103: Business associate (4)(i)')],"Every treating provider receiving information becomes the pharmacy's business associate.")
add(True,'BAA는 applicable privacy rule이 금지한 사용을 일반 면제하지 않는다. 504(e)(2)(i)의 제한과 명시적 허용 범위를 함께 따른다.',[('cfr45-164.504','164.504(e)(2)(i),(4)'),(P,'164.502(a)(3)')],'A BAA does not authorize uses that the applicable privacy rules otherwise prohibit.')
add(False,'서명된 BAA는 otherwise prohibited한 모든 사용을 허용하는 포괄 면허가 아니다. 허용·요구 범위와 safeguards를 따라야 한다.',[('cfr45-164.504','164.504(e)(2)(i),(4)'),(P,'164.502(a)(3)')],'Signing a BAA permits any otherwise prohibited use of the information.')
add(True,'164.506(a),(c)(2)의 허용된 치료 공개는 PHI라는 이유만으로 별도 authorization를 일반적으로 요구하지 않는다. 다른 법의 특별 보호나 508(a) 예외가 있으면 별도 검토한다.',[('cfr45-164.506','164.506(a),(c)(2)'),('cfr45-164.508','164.508(a)(1)-(4)')],'A permitted treatment disclosure generally does not require separate patient authorization merely because PHI is involved.')
add(False,'모든 처방 clarification에 별도 서명을 요구한다는 절대 주장은 164.506의 치료 공개 permission과 맞지 않는다. 특수 정보·법률은 별도이지 이처럼 blanket rule은 아니다.',[('cfr45-164.506','164.506(a),(c)(2)'),('cfr45-164.508','164.508(a)')],'Every treatment clarification involving PHI requires a separate signed authorization before discussion.')
add(True,'기술적 login 보유가 무관한 친구 기록 조회의 허용 목적을 만들지 않는다. 502(a)의 허용 범위와 514(d)(2)의 직무별 필요 접근을 따른다.',[(P,'164.502(a)'),('cfr45-164.514','164.514(d)(2)')],"The friend's record cannot be accessed simply because the employee has technical access.")
add(False,'시스템 접근 가능성과 lawful treatment purpose는 다르다. 호기심으로 친구 기록을 여는 행위에 치료 근거를 부여하지 않는다.',[(P,'164.502(a)'),('cfr45-164.514','164.514(d)(2)')],"A pharmacy login makes curiosity access to a friend's record a treatment activity.")
add(True,'TPO permission은 실제 기능·목적과 다른 적용 의무에 종속된다. 업무에 TPO라는 이름을 붙였다고 모든 행위가 합법화되지 않는다.',[('cfr45-164.506','164.506(a),(c)'),(P,'164.502(a)')],'TPO is a defined permitted-use framework rather than a label that validates any activity.')
add(False,'실제 목적을 무시한 TPO 명칭만으로 공개·접근이 허용되는 것은 아니다.',[('cfr45-164.506','164.506(a),(c)'),(P,'164.502(a)')],'Describing an activity as TPO makes it lawful regardless of its actual purpose.')
add(True,'치료 공개 permission이 있어도 530(c)의 적절한 administrative·technical·physical privacy safeguards는 남는다. 합법적인 소통에서 정보 보호를 유지한다.',[('cfr45-164.506','164.506(a)'),('cfr45-164.530','164.530(c)'),(M,'9.01(16)')],'The pharmacy must still protect confidentiality while carrying out an authorized treatment communication.')
add(False,'치료 목적은 비밀유지 safeguards 전체의 예외가 아니다. 허용된 소통도 적절하게 보호해야 한다.',[('cfr45-164.506','164.506(a)'),('cfr45-164.530','164.530(c)'),(M,'9.01(16)')],'A treatment purpose eliminates confidentiality safeguards during communication.')
add(True,'164.502(b)(2)(i)는 health care provider에 대한 treatment disclosure 또는 provider의 treatment request를 minimum necessary에서 제외한다. 본문 Case A는 그 provider 간 치료 경로다.',[(P,'164.502(b)(2)(i)')],'The rule contains an exception for the described provider-to-provider treatment disclosure or request.')
add(False,'164.502(b)(2)(i)에 명시된 provider treatment disclosure/request 예외가 실제 존재한다.',[(P,'164.502(b)(2)(i)')],'The rule has no exception for provider-to-provider treatment disclosures.')
add(True,'외부 provider 치료 공개의 minimum necessary 예외는 관계없는 내부 기록을 호기심으로 조회하는 권한이 아니다. workforce 직무 접근 제한과 기본 permission이 남는다.',[(P,'164.502(a),(b)(2)(i)'),('cfr45-164.514','164.514(d)(2)')],'The exception does not create unrestricted curiosity access for the pharmacy workforce.')
add(False,'provider 치료 공개 예외와 무관한 내부 workforce 접근은 서로 다르다. 본문 직원은 assigned duty 외의 기록을 보고 있어 이 예외를 근거로 삼을 수 없다.',[(P,'164.502(a),(b)(2)(i)'),('cfr45-164.514','164.514(d)(2)')],'The treatment-disclosure exception authorizes workforce access to unrelated patient files.')
add(True,'minimum necessary의 특정 예외가 기본 허용 근거나 530(c) safeguards까지 없애지는 않는다. 예외의 정확한 범위에 머물러야 한다.',[(P,'164.502(a),(b)(2)'),('cfr45-164.530','164.530(c)')],'An applicable exception to minimum necessary is not an exception to every privacy obligation.')
add(False,'하나의 minimum necessary 예외를 모든 privacy requirement 면제로 확장한 오류다. 허용 목적·다른 제한·safeguards는 여전히 검토한다.',[(P,'164.502(a),(b)(2)'),('cfr45-164.530','164.530(c)')],'A minimum-necessary exception removes all other privacy requirements.')
add(True,'502(b)(2)는 provider 치료·본인·authorization·법정 공개 등의 예외를 구분한다. 수령자와 실제 목적을 먼저 알아야 적용 여부를 정할 수 있다.',[(P,'164.502(b)(1)-(2)'),('cfr45-164.514','164.514(d)')],'The purpose and recipient must be identified before deciding how the requirement applies.')
add(False,'수령자와 목적에 따른 502(b)(2)의 명시적 예외가 있으므로 모든 경우에 identical analysis를 적용한다는 주장은 틀리다.',[(P,'164.502(b)(1)-(2)')],'The minimum-necessary analysis is identical for every recipient and purpose.')
add(True,'마케팅의 실제 목적과 적용 authorization를 확인해야 한다. 508(a)(3)은 제한된 대면·명목가치 선물 예외를 두지만 식별가능 환자명단을 promoter에게 주는 본문 사실이 그 예외를 증명하지 않는다.',[('cfr45-164.508','164.508(a)(3)'),('cfr45-164.506','164.506(a),(b)(2)')],'A marketing use must be evaluated under its actual authorization requirements rather than relabeled as treatment.')
add(False,'treatment support라는 이름만으로 실제 promotional list 제공을 치료 permission으로 바꾸지 못한다.',[('cfr45-164.508','164.508(a)(3)-(4)'),('cfr45-164.506','164.506(a)')],'Calling the promotion treatment support establishes a permitted treatment purpose.')
add(True,'수령 promoter가 명단 대가를 지급하는 것은 일반 의료비 payment와 다르다. sale PHI 정의의 실제 조건·예외 및 508(a)(4)의 authorization와 remuneration 고지를 검토한다.',[(P,'164.502(a)(5)(ii)'),('cfr45-164.508','164.508(a)(4)')],'Payment from a promoter does not by itself turn a sale of PHI into permitted health-care payment activity.')
add(False,'어떤 유상 PHI 거래든 의료 payment가 되는 것은 아니다. 명단 대가와 치료비 지급을 혼동했고 sale PHI 요건·예외를 누락한다.',[(P,'164.502(a)(5)(ii)'),('cfr45-164.508','164.508(a)(4)')],'Any paid transaction involving PHI falls within ordinary health-care payment permission.')
add(True,'치료를 받는 데 동의한 사실이 별도 marketing·sale authorization를 자동 충족하지 않는다. 506(b)(2)는 필요한 508 authorization를 일반 consent로 대체할 수 없다고 정한다.',[('cfr45-164.506','164.506(b)(2)'),('cfr45-164.508','164.508(a)(3)-(4),(c)')],"A patient's consent to receive care is not necessarily the authorization needed for an unrelated promotion.")
add(False,'진료 동의는 모든 무관한 홍보 목적의 포괄 authorization가 아니다. 목적·정보·수령자 등 별도 요소를 확인해야 한다.',[('cfr45-164.506','164.506(b)(2)'),('cfr45-164.508','164.508(a)(3)-(4),(c)')],"Agreement to receive pharmacy care authorizes every unrelated promotional use of the patient's information.")
add(False,'필요한 공개 근거나 유효한 authorization 없이 먼저 공개하고 사후 결정하는 경로는 허용되지 않는다. 508(a)(1)의 원칙을 적용한다.',[('cfr45-164.508','164.508(a)(1),(3)-(4)')],'The pharmacy may disclose first and decide the required authorization after the promoter uses the list.')
add(True,'510(b)는 patient agreement·기회·전문 판단 등 요건에 맞으면 실제 care 참여에 직접 관련된 정보를 가족에게 공유할 수 있게 한다. 별도 broad written authorization가 항상 필요한 것은 아니다.',[('cfr45-164.510','164.510 introductory text, (b)(1)-(3)')],'Relevant information may be shared through the applicable patient-agreement or other permitted pathway.')
add(False,'본문에는 환자 동의와 투약 도움이라는 관련 목적이 있다. 510(b)는 해당 범위의 공유를 허용할 수 있으므로 broad written authorization 없이는 어떤 설명도 못 한다는 절대 주장은 틀리다.',[('cfr45-164.510','164.510 introductory text, (b)(1)-(3)')],'Family pickup prevents any relevant explanation unless a separate broad written authorization is obtained.')
add(True,'가족 신분만으로 unrelated sensitive records 전체 접근이 허용되지 않는다. 510(b)의 실제 care/payment 참여 범위와 별도 personal representative 권한을 확인해야 한다.',[('cfr45-164.510','164.510(b)(1)-(3)'),(P,'164.502(g)')],'Family relationship alone does not establish unrestricted access to unrelated records.')
add(False,'한 처방 pickup 참여만으로 무관한 모든 health records 접근권이 생기지 않는다. 관련 범위를 넘는 정보에는 별도 근거가 필요하다.',[('cfr45-164.510','164.510(b)(1)-(3)'),(P,'164.502(g)')],'A family member collecting one prescription is entitled to all unrelated health records.')
add(True,'510(b)(1)(i)의 정보 범위는 해당인의 care 또는 payment 참여에 directly relevant한 PHI이다. 친족 관계 자체가 아니라 실제 참여가 기준이다.',[('cfr45-164.510','164.510(b)(1)(i),(3)')],"The scope of information should relate to the person's actual involvement in care or payment.")
add(False,'하나의 거래 참여는 관련 없는 정보 공개를 허용하는 근거가 아니다. direct relevance 경계를 지켜야 한다.',[('cfr45-164.510','164.510(b)(1)(i),(3)')],'Involvement in one transaction authorizes disclosure unrelated to that involvement.')
add(False,'친족이라는 이유만으로 환자의 관련 반대를 무시할 수 없다. agreement/opportunity-to-object와 해당 대리권 등 실제 법적 경로를 검토한다.',[('cfr45-164.510','164.510(b)(2)-(3)'),(P,'164.502(g)')],"A family member's request overrides the patient's relevant objection solely because of kinship.")
add(True,'보험료 지급 사실만으로 minor의 보호되는 서비스 기록 접근권이 결정되지 않는다. 502(g)(3)의 independent-consent 예외와 MA12F의 비밀유지·공개 조건을 실제 서비스에 맞게 적용한다.',[(P,'164.502(g)(3)'),('ma112-12f','§12F: minor consent and confidentiality paragraphs')],"Payment of insurance premiums alone does not settle access to the protected service's records.")
add(False,'보험료 납부는 보호 서비스 기록 전체에 대한 자동 접근 근거가 아니다. 서비스별 independent consent와 confidentiality를 확인해야 한다.',[(P,'164.502(g)(3)'),('ma112-12f','§12F: confidentiality paragraph')],'Paying the premiums automatically gives the parent unrestricted access to the protected service record.')
add(True,'서비스에 한정된 consent 권한을 모든 치료의 무제한 권한으로 확장하면 안 된다. 다만 MA12F는 혼인 등 status-based 범주와 질환·HIV 예방의 service-based 범주를 함께 두므로 본문에서 어느 경로인지 특정할 필요가 있다.',[('ma112-12f','§12F: second paragraph, clauses (i)-(vi) and proviso')],'A specific minor-consent provision should not be generalized to all unrelated medical care.')
add(False,'하나의 특정 서비스 동의 권한만으로 모든 unrelated treatment의 unrestricted consent를 확정할 수 없다. 12F의 각 범주를 확인해야 하며 구체 서비스가 없는 본문은 보완 대상이다.',[('ma112-12f','§12F: second paragraph, clauses (i)-(vi) and proviso')],'Consent authority for one specified service establishes unrestricted consent authority for every treatment.')
add(True,'유효한 독립 동의가 있어도 pharmacist의 scope나 제품별 적격조건을 스스로 넓히지 않는다. 12F는 consent 법이고 247CMR9.01(4)는 교육·경험·인정된 scope의 경계를 별도 유지한다. 본문에 특정 제품이 없어 연령기준 숫자는 새로 추정하지 않는다.',[('ma112-12f','§12F: minor consent'),(M,'9.01(4)')],"Product eligibility and pharmacist scope remain separate from the minor's ability to consent.")
add(False,'독립 consent는 제품별 조건과 professional scope를 전부 없애는 예외가 아니다. consent 권한과 실제 수행 권한을 구분한다.',[('ma112-12f','§12F: minor consent'),(M,'9.01(4)')],'Independent consent eliminates product-age and professional-scope restrictions.')
add(True,'MA12F의 해당 기록에는 minor의 written consent·proper judicial order 등 실제 근거가 필요하며 life/limb 위험 시 부모 통지 문언도 있다. 관계만으로 자동 예외를 만들지 않는다. 다른 서비스별 특별법은 그때 별도 확인한다.',[('ma112-12f','§12F: final confidentiality and danger-notification paragraph'),(P,'164.502(g)(3)')],'A legal record-disclosure exception must be identified rather than assumed from the family relationship.')
add(False,'부모의 모든 요청이 자동 예외가 되는 것은 아니다. MA12F의 구체적 consent/order·중대한 위험 통지 조건 및 502(g)(3)을 보아야 한다.',[('ma112-12f','§12F: final confidentiality and danger-notification paragraph'),(P,'164.502(g)(3)')],"Every request from a parent is an automatic exception to the service's confidentiality rules.")
add(True,'520(c)(2)(ii)의 NPP 수령 acknowledgment는 notice를 받았다는 사실을 남긴다. 508의 specific authorization 요건을 대신하는 포괄적 허용이 아니다.',[('cfr45-164.520','164.520(b)(1)(ii)(E),(c)(2)(ii)'),('cfr45-164.508','164.508(a),(c)')],'Acknowledgment of the notice is not unrestricted authorization for future disclosures.')
add(False,'NPP 서명은 모든 향후 PHI 사용·공개를 허용하는 authorization가 아니다. notice와 authorization의 별도 목적·요건을 보아야 한다.',[('cfr45-164.520','164.520(c)(2)(ii)'),('cfr45-164.508','164.508(a),(c)')],'The notice acknowledgment authorizes every future use and disclosure of PHI.')
add(True,'수령 acknowledgment와 필요한 specific authorization를 구분하는 것은 각 문서의 다른 기능을 보존한다. 508(b)(3)의 compound authorization 제한도 있어 notice 서명을 무조건 대체 문서로 취급하면 안 된다.',[('cfr45-164.520','164.520(c)(2)(ii)'),('cfr45-164.508','164.508(b)(3),(c)')],'Separating the acknowledgment from a required specific authorization preserves the distinct purposes.')
add(False,'specific authorization를 언제나 notice acknowledgment로 대체할 수 없다. 508의 목적·정보·수령자·기한·서명 요건 등은 별도이다.',[('cfr45-164.520','164.520(c)(2)(ii)'),('cfr45-164.508','164.508(c)')],'A specific authorization can always be replaced by the notice acknowledgment.')
add(False,'direct-treatment provider에는 emergency 제외 good-faith written acknowledgment 확보 및 실패 시 노력·사유 기록 절차가 있다. 아무 절차가 없다는 진술은 틀리다.',[('cfr45-164.520','164.520(c)(2)(ii),(e)')],'Notice provision has no acknowledgment-related procedure in the described direct-treatment setting.')
add(False,'수령 확인으로 access·amendment·confidential communications 권리를 전부 포기하지 않는다. 520은 오히려 이 권리를 고지하도록 하고 530(h)는 care 조건의 waiver를 금지한다.',[('cfr45-164.520','164.520(b)(1)(iv)(B)-(D)'),('cfr45-164.524','164.524(a)'),('cfr45-164.526','164.526(a)'),('cfr45-164.530','164.530(h)')],'Signing the notice waives all access, amendment, and confidential-communication rights.')
